package com.yuegang.zhihui.system.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.system.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public final class SystemDictionaryAdministrationService{private final JdbcTemplate jdbc;public SystemDictionaryAdministrationService(DataSource d){jdbc=new JdbcTemplate(d);}public List<DictionaryAdminView>all(){return jdbc.query("SELECT id,code,name,enabled,version FROM system_dictionary_type ORDER BY code",(r,n)->view(r));}@Transactional public DictionaryAdminView saveType(SaveDictionaryTypeRequest c){int changed=c.version()==0?jdbc.update("INSERT INTO system_dictionary_type(id,code,name,enabled) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),enabled=VALUES(enabled),version=version+1",next(),c.code(),c.name(),c.enabled()):jdbc.update("UPDATE system_dictionary_type SET name=?,enabled=?,version=version+1 WHERE code=? AND version=?",c.name(),c.enabled(),c.code(),c.version());if(changed<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return byCode(c.code());}@Transactional public DictionaryAdminView saveItem(String code,SaveDictionaryItemRequest c){Long type=jdbc.query("SELECT id FROM system_dictionary_type WHERE code=?",r->r.next()?r.getLong(1):null,code);if(type==null)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);int changed=c.version()==0?jdbc.update("INSERT INTO system_dictionary_item(id,type_id,item_key,item_value,sort_order,enabled) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE item_value=VALUES(item_value),sort_order=VALUES(sort_order),enabled=VALUES(enabled),version=version+1",next(),type,c.key(),c.value(),c.sortOrder(),c.enabled()):jdbc.update("UPDATE system_dictionary_item SET item_value=?,sort_order=?,enabled=?,version=version+1 WHERE type_id=? AND item_key=? AND version=?",c.value(),c.sortOrder(),c.enabled(),type,c.key(),c.version());if(changed<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return byCode(code);}private DictionaryAdminView byCode(String code){return jdbc.query("SELECT id,code,name,enabled,version FROM system_dictionary_type WHERE code=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return view(r);},code);}private DictionaryAdminView view(java.sql.ResultSet r)throws java.sql.SQLException{long id=r.getLong(1);var items=jdbc.query("SELECT item_key,item_value,sort_order,enabled,version FROM system_dictionary_item WHERE type_id=? ORDER BY sort_order,item_key",(i,n)->new DictionaryAdminView.Item(i.getString(1),i.getString(2),i.getInt(3),i.getBoolean(4),i.getLong(5)),id);return new DictionaryAdminView(r.getString(2),r.getString(3),r.getBoolean(4),r.getLong(5),items);}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
